  "Client": {
    "description": "Client represents a client configuration for Xray inbounds with traffic limits and settings.",
    "properties": {
      "activateBefore": {
        "description": "ActivateBefore is the delayed-start activation deadline (ms). While the\nclient is still un-activated (negative expiryTime) past this timestamp,\nthe client is treated as expired. 0 disables the deadline.",
        "type": "integer"
      },
      "allowedIPs": {
        "items": {
          "type": "string"
        },
        "type": "array"
      },
      "allowedIPsByInbound": {
        "additionalProperties": {
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "type": "object"
      },
      "auth": {
        "description": "Auth password (Hysteria)",
        "type": "string"
      },
      "comment": {
        "description": "Client comment",
        "type": "string"
      },
      "created_at": {
        "description": "Creation timestamp",
        "type": "integer"
      },
      "email": {
        "description": "Client email identifier",
        "type": "string"
      },
      "enable": {
        "description": "Whether the client is enabled",
        "type": "boolean"
      },
      "expiryTime": {
        "description": "Expiration timestamp",
        "type": "integer"
      },
      "flow": {
        "description": "Flow control (XTLS)",
        "type": "string"
      },
      "forwardedPorts": {
        "type": "string"
      },
      "group": {
        "description": "Logical grouping label",
        "type": "string"
      },
      "id": {
        "description": "Unique client identifier",
        "type": "string"
      },
      "keepAlive": {
        "type": "integer"
      },
      "limitDevice": {
        "description": "LimitDevice caps how many distinct HWID-identified devices may fetch\nthis client's subscription. 0 (the default) disables both tracking and\nenforcement, so existing clients are unaffected.",
        "type": "integer"
      },
      "limitIp": {
        "description": "IP limit for this client",
        "type": "integer"
      },
      "password": {
        "description": "Client password",
        "type": "string"
      },
      "preSharedKey": {
        "type": "string"
      },
      "privateKey": {
        "description": "Native WireGuard/AmneziaWG peer material. These fields remain optional\nfor the other Xray protocols and are persisted with the shared client\nrecord so one client identity can be attached to several inbounds.",
        "type": "string"
      },
      "publicKey": {
        "type": "string"
      },
      "renewalDay": {
        "description": "RenewalDay: for RenewalMode=2 the weekday (0=Sunday .. 6=Saturday);\nfor RenewalMode=1 an optional day-of-month (1-28). 0 means \"inherit\nthe anchor from the current expiry\".",
        "type": "integer"
      },
      "renewalMode": {
        "description": "RenewalMode selects the auto-renew schedule used when a renewal fires:\n0 = rolling whole Reset-day steps (legacy behavior), 1 = whole calendar\nmonths, 2 = a fixed weekday (RenewalDay).",
        "type": "integer"
      },
      "reset": {
        "description": "Reset period in days",
        "type": "integer"
      },
      "reverse": {
        "allOf": [
          {
            "$ref": "#/components/schemas/ClientReverse"
          }
        ],
        "description": "VLESS simple reverse proxy settings",
        "nullable": true
      },
      "security": {
        "description": "Security method (e.g., \"auto\", \"aes-128-gcm\")",
        "type": "string"
      },
      "subId": {
        "description": "Subscription identifier",
        "type": "string"
      },
      "subLastUpdatedAt": {
        "type": "integer"
      },
      "subLastUserAgent": {
        "type": "string"
      },
      "tgId": {
        "description": "Telegram user ID for notifications",
        "type": "integer"
      },
      "totalGB": {
        "description": "Total traffic limit in GB",
        "type": "integer"
      },
      "updated_at": {
        "description": "Last update timestamp",
        "type": "integer"
      }
    },
    "required": [
      "activateBefore",
      "comment",
      "email",
      "enable",
      "expiryTime",
      "limitDevice",
      "limitIp",
      "renewalDay",
      "renewalMode",
      "reset",
      "security",
      "subId",
      "tgId",
      "totalGB"
    ],
    "type": "object"
  },
